package dev.recipeeditor.companionprotocol;
import com.google.gson.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import static org.junit.jupiter.api.Assertions.*;
final class CompanionProtocolTest {
    @Test void handshakeRoundTripAndRequestIdentity()throws Exception {final var p=new JsonObject();p.addProperty("clientNonce",SessionCredentials.nonce());final var expected=new ProtocolMessage(MessageType.HANDSHAKE,"request-1",p);final var stream=new ByteArrayOutputStream();new ProtocolCodec().write(stream,expected);assertEquals(expected,new ProtocolCodec().read(new ByteArrayInputStream(stream.toByteArray())));}
    @ParameterizedTest @ValueSource(strings={"{}","{\"protocolVersion\":2,\"messageType\":\"PING\",\"requestId\":\"x\",\"payload\":{}}","{\"protocolVersion\":1,\"messageType\":\"EXECUTE_COMMAND\",\"requestId\":\"x\",\"payload\":{}}","{\"protocolVersion\":1,\"messageType\":\"PING\",\"requestId\":\"x\",\"payload\":null}","{\"protocolVersion\":1,\"protocolVersion\":1,\"messageType\":\"PING\",\"requestId\":\"x\",\"payload\":{}}"}) void rejectsInvalidMessages(final String json)throws Exception {final var b=new ByteArrayOutputStream();final var out=new DataOutputStream(b);final byte[] bytes=json.getBytes(StandardCharsets.UTF_8);out.writeInt(bytes.length);out.write(bytes);assertThrows(IOException.class,()->new ProtocolCodec().read(new ByteArrayInputStream(b.toByteArray())));}
    @Test void frameLengthAndTruncationAreCheckedBeforeAllocation()throws Exception {final var b=new ByteArrayOutputStream();new DataOutputStream(b).writeInt(Integer.MAX_VALUE);assertThrows(IOException.class,()->new ProtocolCodec().read(new ByteArrayInputStream(b.toByteArray())));assertThrows(IOException.class,()->ProtocolCodec.parse("[[".getBytes(StandardCharsets.UTF_8)));assertThrows(IOException.class,()->ProtocolCodec.parse(new byte[]{(byte)0xff}));}
    @Test void hmacIsRoleAndNonceBoundAndTokenNeverAppearsInToString(){final var c=new SessionCredentials(1,"127.0.0.1",12345,SessionCredentials.nonce(),"session");final var a=SessionCredentials.nonce();final var b=SessionCredentials.nonce();assertNotEquals(c.proof("server",a,b),c.proof("client",a,b));assertNotEquals(c.proof("server",a,b),c.proof("server",a,SessionCredentials.nonce()));assertFalse(c.toString().contains(c.token()));assertThrows(IllegalArgumentException.class,()->new SessionCredentials(1,"0.0.0.0",12345,c.token(),"session"));}
    @Test void chunksSpanRecordsAndVerifyIntegrity()throws Exception {final var recipe=new RuntimeData.Recipe("test:large","test:type","test:serializer","Test","fixture",RuntimeData.Support.PARTIALLY_SUPPORTED,new JsonObject(),"unit test",List.of("x".repeat(100000)));final var frames=new ArrayList<ProtocolMessage>();new RecordTransfer().send(frames::add,"sync",MessageType.RECIPE_DATA,"snapshot",List.of(recipe),new JsonObject(),()->false);assertTrue(frames.size()>2);final var queue=new ArrayDeque<>(frames);assertEquals(List.of(recipe),new RecordTransfer().receive(queue::remove,"sync",MessageType.RECIPE_DATA,RuntimeData.Recipe.class,p->{}).records());frames.get(frames.size()-1).payload().addProperty("sha256","0".repeat(64));final var broken=new ArrayDeque<>(frames);assertThrows(IOException.class,()->new RecordTransfer().receive(broken::remove,"sync",MessageType.RECIPE_DATA,RuntimeData.Recipe.class,p->{}));}
    @Test void rejectsOutOfOrderMixedRequestAndCancelledTransfer()throws Exception {final var frames=new ArrayList<ProtocolMessage>();new RecordTransfer().send(frames::add,"sync",MessageType.MOD_LIST_DATA,"snapshot",List.of(new RuntimeData.Mod("test","1","Test")),new JsonObject(),()->false);frames.get(0).payload().addProperty("sequence",8);final var queue=new ArrayDeque<>(frames);assertThrows(IOException.class,()->new RecordTransfer().receive(queue::remove,"sync",MessageType.MOD_LIST_DATA,RuntimeData.Mod.class,p->{}));assertThrows(IOException.class,()->new RecordTransfer().send(frames::add,"x",MessageType.MOD_LIST_DATA,"s",List.of("data"),new JsonObject(),()->true));}
}
